"""public_check-style run of the public fixtures under the scored candidate policy."""
import json, math, os, pathlib, subprocess, sys, time
sys.path.insert(0, '/workspace')
from candidate_policy import candidate_setup


def strict(raw):
    def pairs(items):
        o = {}
        for k, v in items:
            if k in o:
                raise ValueError('dup')
            o[k] = v
        return o
    return json.loads(raw.decode('utf-8'), object_pairs_hook=pairs,
                      parse_constant=lambda s: (_ for _ in ()).throw(ValueError('nonfinite')),
                      parse_float=float)


def run(candidate, data, timeout=180):
    env = {'PATH': os.environ.get('PATH', '/usr/local/bin:/usr/bin:/bin'),
           'LANG': 'C.UTF-8', 'HOME': '/workspace',
           'TMPDIR': os.environ.get('TMPDIR', '/workspace/tmp'),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONHASHSEED': '0'}
    t0 = time.time()
    p = subprocess.Popen([sys.executable, '-B', str(candidate)], stdin=subprocess.PIPE,
                         stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env,
                         preexec_fn=candidate_setup)
    out, err = p.communicate(data.encode('utf-8'), timeout=timeout)
    code = p.returncode
    if code != 0:
        raise RuntimeError('exit %d stderr=%s' % (code, err[:400]))
    if not out.strip():
        raise RuntimeError('empty output')
    return strict(out), time.time() - t0, err


def same(a, b):
    if type(a) is not type(b):
        return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b


def main():
    here = pathlib.Path('/workspace')
    fixtures = json.loads((here / 'examples/checks.json').read_text())
    bad = 0
    for i, f in enumerate(fixtures):
        data = f.get('raw') or json.dumps(f['request'], separators=(',', ':'))
        try:
            got, el, err = run(here / 'submission/main.py', data)
        except Exception as exc:
            print('FAIL fixture %d: %s' % (i, exc))
            bad += 1
            continue
        ok = same(got, f['response'])
        print('fixture %d %s in %.2fs%s' % (i, 'PASS' if ok else 'MISMATCH', el,
                                            '' if ok else ' got=%s want=%s' % (json.dumps(got)[:200], json.dumps(f['response'])[:200])))
        if not ok:
            bad += 1
    print('PASS %d public executable checks' % len(fixtures) if not bad else 'FAILURES %d' % bad)
    return 1 if bad else 0


if __name__ == '__main__':
    sys.exit(main())
